#!/bin/bash
# DEPLOY_v2_final — جولة الإغلاق: تقطيع المرتِّب بدل قصّه، ثم
# فحص موجّه ← Smoke ← Full Gate (مرة واحدة إن نجح Smoke).
set -u
cd /opt/LegalMind || exit 1
cat > /tmp/v2f.b64 <<'B64EOF'

B64EOF
base64 -d /tmp/v2f.b64 > /tmp/v2f.tgz || { echo "B64_FAIL"; exit 1; }
tar xzf /tmp/v2f.tgz -C /opt/LegalMind || { echo "UNTAR_FAIL"; exit 1; }
set -a; . /opt/LegalMind/deploy/.env; set +a
nohup /opt/LegalMind/admin/.venv/bin/python \
      /opt/LegalMind/tools/v2_close.py > /tmp/v2final.log 2>&1 &
disown
echo "بدأ. تابع:  tail -f /tmp/v2final.log"
